export default function AlertPanel({ alerts = [] }) {
  if (!alerts.length) return (
    <div style={{ background:'linear-gradient(145deg, #141826, #1C2133)', border:'1px solid rgba(255,255,255,0.07)', borderRadius:20, padding:'20px 24px', display:'flex', alignItems:'center', gap:12, animation:'fadeUp 0.5s ease 0.3s both' }}>
      <div style={{ fontSize:20 }}>✨</div>
      <div>
        <div style={{ fontSize:14, fontWeight:600, color:'var(--text-primary)', fontFamily:'var(--font-body)' }}>All stocks healthy</div>
        <div style={{ fontSize:12, color:'var(--text-muted)', marginTop:2 }}>No alerts — your portfolio is performing well. Keep the momentum going.</div>
      </div>
    </div>
  );

  return (
    <div style={{ background:'linear-gradient(145deg, #141826, #1C2133)', border:'1px solid rgba(255,255,255,0.07)', borderRadius:20, overflow:'hidden', animation:'fadeUp 0.5s ease 0.3s both' }}>
      <div style={{ padding:'14px 22px', borderBottom:'1px solid var(--border)', display:'flex', alignItems:'center', gap:10 }}>
        <div style={{ width:8, height:8, borderRadius:'50%', background:'#F87171', animation:'pulse-soft 1.5s ease infinite' }}/>
        <span style={{ fontSize:12, color:'var(--text-secondary)', letterSpacing:'0.06em', textTransform:'uppercase', fontFamily:'var(--font-body)', fontWeight:600 }}>
          {alerts.length} alert{alerts.length > 1 ? 's' : ''} need your attention
        </span>
      </div>

      {alerts.map((a, i) => (
        <div key={i} style={{ padding:'18px 22px', borderBottom: i < alerts.length-1 ? '1px solid var(--border)' : 'none', display:'flex', gap:14, alignItems:'flex-start', transition:'background 0.2s', cursor:'default' }}
          onMouseEnter={e => e.currentTarget.style.background = 'var(--bg-elevated)'}
          onMouseLeave={e => e.currentTarget.style.background = 'transparent'}
        >
          <div style={{ width:32, height:32, borderRadius:10, flexShrink:0, background: a.severity==='danger' ? 'rgba(248,113,113,0.1)' : 'rgba(251,191,36,0.1)', border:`1px solid ${a.severity==='danger' ? 'rgba(248,113,113,0.25)' : 'rgba(251,191,36,0.25)'}`, display:'flex', alignItems:'center', justifyContent:'center', fontSize:14 }}>
            {a.severity === 'danger' ? '⚠️' : '📉'}
          </div>
          <div style={{ flex:1, minWidth:0 }}>
            <div style={{ fontFamily:'var(--font-body)', fontWeight:700, fontSize:14, color: a.severity==='danger' ? '#F87171' : '#FBBF24', marginBottom:5 }}>
              {a.headline}
            </div>
            <div style={{ fontSize:13, color:'var(--text-secondary)', lineHeight:1.6, marginBottom:8 }}>
              {a.detail}
            </div>
            <div style={{ display:'flex', alignItems:'center', gap:10, flexWrap:'wrap' }}>
              <span style={{ fontFamily:'var(--font-body)', fontSize:12, color: a.severity==='danger' ? '#F87171' : '#FBBF24', background: a.severity==='danger' ? 'rgba(248,113,113,0.1)' : 'rgba(251,191,36,0.1)', padding:'3px 10px', borderRadius:20, border:`1px solid ${a.severity==='danger' ? 'rgba(248,113,113,0.2)' : 'rgba(251,191,36,0.2)'}` }}>
                {a.cost_impact}
              </span>
              <span style={{ fontSize:12, color:'var(--text-muted)', fontStyle:'italic' }}>
                → {a.action_prompt}
              </span>
            </div>
          </div>
        </div>
      ))}
    </div>
  );
}
